#include "stdlib/blas/base/dgemm.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/xerbla.h"
#include "stdlib/strided/base/stride2offset.h"

/**
* Performs the matrix-matrix operation `C = α*op(A)*op(B) + β*C` where `op(X)` is either `op(X) = X` or `op(X) = X^T`, `α` and `β` are scalars, `A`, `B`, and `C` are matrices, with `op(A)` an `M` by `K` matrix, `op(B)` a `K` by `N` matrix, and `C` an `M` by `N` matrix.
*
* @param layout  storage layout
* @param transA  specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param transB  specifies whether `B` should be transposed, conjugate-transposed, or not transposed
* @param M       number of rows in the matrix `op(A)` and number of rows in the matrix `C`
* @param N       number of columns in the matrix `op(B)` and number of columns in the matrix `C`
* @param K       number of columns in the matrix `op(A)` and number of rows in the matrix `op(B)`
* @param alpha   scalar constant
* @param A       first matrix
* @param LDA     stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param B       second matrix
* @param LDB     stride of the first dimension of `B` (a.k.a., leading dimension of the matrix `B`)
* @param beta    scalar constant
* @param C       third matrix
* @param LDC     stride of the first dimension of `C` (a.k.a., leading dimension of the matrix `C`)
*/
void API_SUFFIX(c_dgemm)( const CBLAS_LAYOUT layout, const CBLAS_TRANSPOSE transA, const CBLAS_TRANSPOSE transB, const CBLAS_INT M, const CBLAS_INT N, const CBLAS_INT K, const double alpha, const double *A, const CBLAS_INT LDA, const double *B, const CBLAS_INT LDB, const double beta, double *C, const CBLAS_INT LDC) {
	CBLAS_INT vala;
	CBLAS_INT valb;
	CBLAS_INT valc;
	CBLAS_INT sa1;
	CBLAS_INT sa2;
	CBLAS_INT sb1;
	CBLAS_INT sb2;
	CBLAS_INT sc1;
	CBLAS_INT sc2;
	CBLAS_INT va;
	CBLAS_INT vb;
	CBLAS_INT vc;
	// Perform input argument validation...
	if ( layout != CblasRowMajor && layout != CblasColMajor ) {
		c_xerbla( 1, "c_dgemm", "Error: invalid argument. First argument must be a valid storage layout. Value: `%d`.", layout );
	}
	if ( transA != CblasTrans && transA != CblasConjTrans && transA != CblasNoTrans ) {
		c_xerbla( 2, "c_dgemm", "Error: invalid argument. Second argument must be a valid transpose operation. Value: `%d`.", transA );
	}
	if ( transB != CblasTrans && transB != CblasConjTrans && transB != CblasNoTrans ) {
		c_xerbla( 3, "c_dgemm", "Error: invalid argument. Third argument must be a valid transpose operation. Value: `%d`.", transB );
	}
	if ( M < 0 ) {
		c_xerbla( 4, "c_dgemm", "Error: invalid argument. Fourth argument must be a nonnegative integer. Value: `%d`.", M );
	}
	if ( N < 0 ) {
		c_xerbla( 5, "c_dgemm", "Error: invalid argument. Fifth argument must be a nonnegative integer. Value: `%d`.", N );
	}
	if ( K < 0 ) {
		c_xerbla( 6, "c_dgemm", "Error: invalid argument. Sixth argument must be a nonnegative integer. Value: `%d`.", K );
	}
	// LDA check
	if (
		(layout == CblasRowMajor && transA == CblasNoTrans) ||
		(layout == CblasColMajor && transA != CblasNoTrans)
	) {
		va = K;
	} else {
		va = M;
	}
	// max (1, va)
	if ( va < 1 ) {
		vala = 1;
	} else {
		vala = va;
	}
	if ( LDA < vala ) {
		c_xerbla( 9, "c_dgemm", "Error: invalid argument. Ninth argument must be at least the maximum of 1 and the number of rows in the matrix `op(A)`. Value: `%d`.", LDA );
	}
	// LDB check
	if (
		(layout == CblasRowMajor && transB == CblasNoTrans) ||
		(layout == CblasColMajor && transB != CblasNoTrans)
	) {
		vb = N;
	} else {
		vb = K;
	}
	// max (1, vb)
	if ( vb < 1 ) {
		valb = 1;
	} else {
		valb = vb;
	}
	if ( LDB < valb ) {
		c_xerbla( 11, "c_dgemm", "Error: invalid argument. Eleventh argument must be at least the maximum of 1 and the number of rows in the matrix `op(B)`. Value: `%d`.", LDB );
	}
	// LDC check
	if (layout == CblasRowMajor) {
		vc = N;
	} else { // layout == CblasColMajor
		vc = M;
	}
	// max (1, vc)
	if ( vc < 1 ) {
		valc = 1;
	} else {
		valc = vc;
	}
	if ( LDC < valc ) {
		c_xerbla( 14, "c_dgemm", "Error: invalid argument. Fourteenth argument must be at least the maximum of 1 and the number of rows in the matrix `C`. Value: `%d`.", LDC );
	}
	// Check if we can early return...
	if ( M == 0 || N == 0 || ((alpha == 0.0 || K == 0) && beta == 1.0)) {
		// TODO: Check accuracy with ndarray.js
		return;
	}
	if (layout == CblasColMajor) {
		sa1 = 1; sa2 = LDA;
		sb1 = 1; sb2 = LDB;
		sc1 = 1; sc2 = LDC;
	} else { // layout == CblasRowMajor
		sa1 = LDA; sa2 = 1;
		sb1 = LDB; sb2 = 1;
		sc1 = LDC; sc2 = 1;
	}
	API_SUFFIX(c_dgemm_ndarray)( transA, transB, M, N, K, alpha, A, sa1, sa2, 0, B, sb1, sb2, 0, beta, C, sc1, sc2, 0 );
	return;
}
